	router := New()

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/test/john/smith/is/super/great", nil)
	router.ServeHTTP(w, req)
	t.Logf("first request status=%d (expected 404)", w.Code)

	router.GET("/test/:name/:last_name/*wild", func(c *Context) {
		t.Logf("handler: name=%q last_name=%q wild=%q (len(params)=%d cap=%d)",
			c.Param("name"), c.Param("last_name"), c.Param("wild"),
			len(c.Params), cap(c.Params))
	})

	t.Logf("after addRoute: engine.maxParams=%d", router.maxParams)

	w2 := httptest.NewRecorder()
	req2 := httptest.NewRequest("GET", "/test/john/smith/is/super/great", nil)
	router.ServeHTTP(w2, req2)
	t.Logf("second request status=%d", w2.Code)

	if got := w2.Code; got != 200 {
		t.Fatalf("status = %d, want 200", got)
	}
}

